class Solution {
public:
    string customSortString(string order, string s) {
        int cnt[26] = {0};
        for (char c : s) {
            cnt[c - 'a']++;
        }
        string res;
        res.reserve(s.size());
        for (char c : order) {
            int idx = c - 'a';
            while (cnt[idx] > 0) {
                res.push_back(c);
                cnt[idx]--;
            }
        }
        for (int i = 0; i < 26; i++) {
            while (cnt[i] > 0) {
                res.push_back(static_cast<char>('a' + i));
                cnt[i]--;
            }
        }
        return res;
    }
};
